 public static class EmbeddedEnvOrderCatalog {
   // Pre-computed ordering metadata from representative Vanilla 5.01 ENV schemas.
   // This contains only property name/type/order, NEVER game file content, values or textures.
   // Specific per-file differences are stored as overrides of a common schema.
   const string SchemaSha256 = "544fedb99e0f73fc81351ab836cc36b8fb8d77379846958b7c1607def761c3ca";
   static readonly string[] Data = new[]{
