     ""
   };
   static Dictionary<string,string[]> rules;
   static readonly object Lock = new object();
   public static bool TryGet(string relative,string path,out string[] order) {
     if(rules==null)lock(Lock){if(rules==null)rules=Build();}
     var rel=(relative??"").ToLowerInvariant();
     var key=rel+"\t"+path;
     if(rules.TryGetValue(key,out order))return true;
     // Prefer the same ENV entry-0 layout for array points without a dedicated schema.
     var wildcard=System.Text.RegularExpressions.Regex.Replace(path,@"/@\d+(?=/|$)","/*");
     if(wildcard!=path && rules.TryGetValue(rel+"\t"+wildcard,out order))return true;
     if(rules.TryGetValue("*\t"+path,out order))return true;
     return wildcard!=path && rules.TryGetValue("*\t"+wildcard,out order);
   }
   static Dictionary<string,string[]> Build() {
     string b64=String.Concat(Data);
     byte[] buffer=Convert.FromBase64String(b64);
     var result=new Dictionary<string,string[]>(StringComparer.Ordinal);
     using(var compressed=new MemoryStream(buffer))
     using(var decompressor=new GZipStream(compressed,CompressionMode.Decompress))
     using(var reader=new StreamReader(decompressor,Encoding.UTF8)){
       string line;
       while((line=reader.ReadLine())!=null) {
         int first=line.IndexOf('\t'), second=line.IndexOf('\t',first+1);
         if(first<1 || second<=first+1)continue;
         string rel=line.Substring(0,first).ToLowerInvariant();
         string path=line.Substring(first+1,second-first-1);
         string order=line.Substring(second+1);
         if(!result.TryAddCompat(rel+"\t"+path,order.Split('|')))throw new InvalidDataException("Duplicate built-in ENV schema: "+path);
       }
     }
     if(result.Count<500)throw new InvalidDataException("Built-in ENV schemas missing or corrupt.");
     return result;
   }
 }
 internal static class DictionarySchemaCompat {
   public static bool TryAddCompat(this Dictionary<string,string[]> dict,string key,string[] val) {
     if(dict.ContainsKey(key))return false;
     dict.Add(key,val);return true;
   }
 }
 public static partial class EnvCanonicalOrder {
   static string RelativeEnv(string file) {
     var full=Path.GetFullPath(file).Replace('/', '\\');
     int at=full.LastIndexOf("\\files\\",StringComparison.OrdinalIgnoreCase);
     if(at>=0)return full.Substring(at+7).Replace('\\','/').ToLowerInvariant();
     at=full.IndexOf("\\dlc\\",StringComparison.OrdinalIgnoreCase);
     if(at>=0)return full.Substring(at+1).Replace('\\','/').ToLowerInvariant();
     at=full.IndexOf("\\environment\\",StringComparison.OrdinalIgnoreCase);
     if(at>=0)return full.Substring(at+1).Replace('\\','/').ToLowerInvariant();
     return "";
   }
   static bool EmbeddedReorder(CVector current,string relative,string path,bool top) {
     var old=current.variables.ToList();
     var ranks=new Dictionary<string,int>(StringComparer.Ordinal);
     if(top){
       for(int i=0;i<Top.Length;i++)ranks[Top[i]]=i;
     }else{
       string[] order;
       if(!EmbeddedEnvOrderCatalog.TryGet(relative,path,out order))return false;
       for(int i=0;i<order.Length;i++)if(!ranks.ContainsKey(order[i]))ranks[order[i]]=i;
     }
     int Rank(CVariable v){
       int val;
       if(top)return ranks.TryGetValue(v.Name??"",out val)?val:Top.Length;
       return ranks.TryGetValue((v.Name??"")+"~"+(v.Type??""),out val)?val:ranks.Count;
     }
     var sorted=old.Select((v,i)=>new{v,i}).OrderBy(v=>Rank(v.v)).ThenBy(v=>v.i).Select(v=>v.v).ToArray();
     if(old.SequenceEqual(sorted))return false;
     current.variables.Clear();current.variables.AddRange(sorted);
     return true;
   }
   static void WalkEmbedded(IEditableVariable node,string relative,string path,bool top,ref int count) {
     var vec=node as CVector;
     if(vec!=null) {
       if(EmbeddedReorder(vec,relative,path,top))count++;
       var occurrences=new Dictionary<string,int>(StringComparer.Ordinal);
       foreach(var child in vec.variables) {
         string key=(child.Name??"")+"~"+(child.Type??"");
         int n=0;occurrences.TryGetValue(key,out n);occurrences[key]=n+1;
         string next=path+"/"+key.Replace("/","_").Replace("\\","_")+"#"+n;
         WalkEmbedded(child,relative,next,false,ref count);
       }
       return;
     }
     var ar=node as CArray;
     if(ar!=null) {
       // Preserve native point/array-entry layout byte-for-byte. The canonical
       // schema orders containers and named properties, never individual curve entries.
       if(path.IndexOf("dataCurveValues",StringComparison.OrdinalIgnoreCase)>=0)return;
       for(int i=0;i<ar.array.Count;i++)WalkEmbedded(ar.array[i],relative,path+(i==0?"/*":"/@"+i),false,ref count);
     }
   }
 }
